WITH cleaned AS (SELECT *, CASE WHEN is_flagged THEN 'Yes' ELSE 'No' END AS is_flagged_label FROM transactions WHERE merchant IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM cleaned), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT merchant, SUM(CASE WHEN merchant = 'Starbucks' THEN is_new_session ELSE 0 END) AS starbucks_is_new_session, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list_2, AVG(amount) AS avg_amount, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list_3 FROM sessions_transactions GROUP BY merchant
